#include "KS/SRC/vector3d_shared.h"

class input_device {
protected:
    int device_id;
public:
    virtual ~input_device();
};

class AISurferController : public input_device {
    enum AI_SURFER_STATE {
        STATE_STANDING,
        STATE_CHASE,
        STATE_DO_TRICK,
        STATE_AVOID_SURFER,
        STATE_BOUNCE_AROUND_WAVE,
        STATE_LAST_STATE
    };
    enum AI_SURFER_SUBSTATE {
        NO_SUBSTATE,
        TRICK_APPROACH,
        TRICK_LAUNCH,
        TRICK_DOING_TRICK,
        TRICK_LANDING,
        TRICK_DONE,
        STATE_LAST_SUBSTATE
    };

    vector3d target, toTube, right, velocity, dir;
    vector3d paddleDirVec;
    AI_SURFER_STATE myState;
    AI_SURFER_SUBSTATE mySubstate;
    float offdh, diffAngle, paddleAngle, toTargetDistance, lastToTargetDistance;
    float relativeVelocityToTarget, lastRelativeVelocityToTarget, toTubeDist;
    float last_toward_tube_velocity, this_toward_tube_velocity;
    vector3d heading;
    float acel, oldAcel;
    void *ksctl;
    bool hitRegionPocket;
    float X, Y, XRight, YRight;
    bool ButtonX, ButtonO, ButtonSq, ButtonTr;
    bool ButtonL1, ButtonL2, ButtonL3, ButtonR1, ButtonR2, ButtonR3;
    bool ButtonSelect, ButtonStart;
    float oldX, oldY, oldXRight, oldYRight;
    bool oldButtonX, oldButtonO, oldButtonSq, oldButtonTr;
    bool oldButtonL1, oldButtonL2, oldButtonL3;
    bool oldButtonR1, oldButtonR2, oldButtonR3;
    bool oldButtonSelect, oldButtonStart;
    int curTrick;

public:
    AISurferController();
};

AISurferController::AISurferController()
{
  myState = STATE_STANDING;
  mySubstate = NO_SUBSTATE;
  curTrick = 0;
  offdh = diffAngle = paddleAngle =0;
  toTargetDistance = lastToTargetDistance = 999999;
  toTubeDist = 0;
  lastRelativeVelocityToTarget = relativeVelocityToTarget = 0;
  heading = vector3d(-1,0,0);

  X = Y = 0;
  ButtonX = ButtonO = ButtonSq = ButtonTr = false;
  ButtonL1 = ButtonL2 = ButtonL3 = false;
  ButtonR1 = ButtonR2 = ButtonR3 = false;
  ButtonStart = ButtonSelect = 0;

  oldX = oldY = 0;
  oldButtonX = oldButtonO = oldButtonSq = oldButtonTr = false;
  oldButtonL1 = oldButtonL2 = oldButtonL3 = false;
  oldButtonR1 = oldButtonR2 = oldButtonR3   = false;
  oldButtonStart = oldButtonSelect = 0;

  acel = oldAcel =0;
  last_toward_tube_velocity = this_toward_tube_velocity = -99999;
  ksctl = 0;
}
